from __future__ import annotations
from typing import Dict, FrozenSet, Iterable, Set

Edge = FrozenSet[int]
ColoredGraph = Dict[Edge, int]

def edge(u: int, v: int) -> Edge:
    return frozenset((u, v))

def has_cycle(edges: Iterable[Edge]) -> bool:
    parent: Dict[int, int] = {}
    def find(x: int) -> int:
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for e in edges:
        u, v = tuple(e)
        ru, rv = find(u), find(v)
        if ru == rv:
            return True
        parent[ru] = rv
    return False

def color_classes(g: ColoredGraph) -> Dict[int, Set[Edge]]:
    cls: Dict[int, Set[Edge]] = {}
    for e, k in g.items():
        cls.setdefault(k, set()).add(e)
    return cls

def admits_total_rainbow_forest(g: ColoredGraph) -> bool:
    return not any(has_cycle(c) for c in color_classes(g).values())

def every_class_a_forest(g: ColoredGraph) -> bool:
    return all(not has_cycle(c) for c in color_classes(g).values())

def verify(g: ColoredGraph) -> bool:
    return admits_total_rainbow_forest(g) == every_class_a_forest(g)

if __name__ == "__main__":
    C3 = {edge(0,1):0, edge(1,2):0, edge(2,0):0}
    rainbow = {edge(0,1):0, edge(1,2):1, edge(2,0):2}
    for name, g in [("mono C3", C3), ("rainbow C3", rainbow)]:
        print(name, "admits TRF =", admits_total_rainbow_forest(g),
              "| equivalence holds =", verify(g))

from __future__ import annotations
from typing import Dict, FrozenSet, List, Set

Edge = FrozenSet[int]
ColoredGraph = Dict[Edge, int]

def edge(u: int, v: int) -> Edge:
    return frozenset((u, v))

def has_cycle(edges) -> bool:
    parent: Dict[int, int] = {}
    def find(x: int) -> int:
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for e in edges:
        u, v = tuple(e); ru, rv = find(u), find(v)
        if ru == rv: return True
        parent[ru] = rv
    return False

def has_mono_cycle(g: ColoredGraph) -> bool:
    cls: Dict[int, Set[Edge]] = {}
    for e, k in g.items():
        cls.setdefault(k, set()).add(e)
    return any(has_cycle(c) for c in cls.values())

def is_minimal_obstruction(g: ColoredGraph) -> bool:
    if not has_mono_cycle(g): return False
    return all(not has_mono_cycle({f:k for f,k in g.items() if f != e}) for e in g)

def is_single_mono_cycle(g: ColoredGraph) -> bool:
    if not g or len(set(g.values())) != 1: return False
    deg: Dict[int,int] = {}
    for e in g:
        for v in e: deg[v] = deg.get(v,0)+1
    if any(d != 2 for d in deg.values()): return False
    vs = set(deg); adj: Dict[int,List[int]] = {v:[] for v in vs}
    for e in g:
        u,w = tuple(e); adj[u].append(w); adj[w].append(u)
    seen = {next(iter(vs))}; stack = list(seen)
    while stack:
        x = stack.pop()
        for y in adj[x]:
            if y not in seen: seen.add(y); stack.append(y)
    return seen == vs

def cycle_graph(n: int) -> ColoredGraph:
    return {edge(i,(i+1)%n):0 for i in range(n)}

if __name__ == "__main__":
    for n in range(3, 11):
        g = cycle_graph(n)
        assert is_minimal_obstruction(g) == is_single_mono_cycle(g) == True
        print(f"C_{n}: minimal obstruction and single mono cycle both True")

from __future__ import annotations
from typing import Dict, FrozenSet, Set

Edge = FrozenSet[int]
ColoredGraph = Dict[Edge, int]

def edge(u: int, v: int) -> Edge:
    return frozenset((u, v))

def components(edges: Set[Edge]) -> int:
    vs: Set[int] = set()
    for e in edges: vs.update(e)
    parent = {v: v for v in vs}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for e in edges:
        u, v = tuple(e); parent[find(u)] = find(v)
    return len({find(v) for v in vs})

def min_deletions_to_cure(g: ColoredGraph) -> int:
    cls: Dict[int, Set[Edge]] = {}
    for e, k in g.items():
        cls.setdefault(k, set()).add(e)
    total = 0
    for c in cls.values():
        vs: Set[int] = set()
        for e in c: vs.update(e)
        total += len(c) - len(vs) + components(c)
    return total

if __name__ == "__main__":
    theta = {edge(a,b):0 for a,b in [(0,1),(1,2),(0,3),(3,2),(0,4),(4,2)]}
    K4 = {edge(a,b):0 for a in range(4) for b in range(a+1,4)}
    print("theta graph min deletions:", min_deletions_to_cure(theta))  # 2
    print("mono K4 min deletions   :", min_deletions_to_cure(K4))      # 3

