function CURE(G, color):
    deleted <- empty set
    for each color k:
        UF <- empty union-find
        for each edge e = {u, v} of color k:
            if FIND(u) == FIND(v):
                add e to deleted        # chord: closes a cycle
            else:
                UNION(u, v)             # keep in spanning forest
    return deleted        # |deleted| = sum of cyclomatic numbers

