        (x1, y1), (x2, y2) = pos[u], pos[v]
        ax.plot([x1, x2], [y1, y2], color=PALETTE[k % len(PALETTE)], lw=3)
    for v, (x, y) in pos.items():
        ax.plot(x, y, "o", color="black", ms=8)
    ax.set_title(title, fontsize=10); ax.axis("equal"); ax.axis("off")

